/**
 * The Jura and the Alps, as the radar shades them — by the **minimum safe
 * altitude** over each band, not by the elevation of the ground itself.
 *
 * At VABB the high ground is scenery on one side of the field. Here it *is* the
 * field. Geneva sits at 1411 ft in a basin barely 12 NM wide: the Jura reaches an
 * MSA of 7000 within 6.7 NM to the north-west, and the Alps fill the whole
 * south-east quadrant, climbing without a break to Mont Blanc at MSA 17,000.
 * **53% of this airspace needs an MSA of 4000 or more**, against 11% of VABB's
 * above its MVA.
 *
 * ## Source and licence
 *
 * Generalised from a third-party elevation contour set, not redistributable under
 * this repository's AGPL-3.0 and so kept local in the gitignored `docs/terrain/`,
 * exactly as the charts are. Only these outlines are in the repository.
 *
 * ## The levels are MSA, and the source contours are not
 *
 * Same conversion as VABB's — `levelFt` is the contour elevation plus 2000 ft of
 * obstacle clearance, applied here so that the number in this file *is* the number
 * the scope prints. Getting this backwards understated every VABB band by 2000 ft.
 *
 * LSGG confirms the offset far better than VABB could, because this field's chart
 * publishes an MSA rose and the terrain can be measured against it directly:
 *
 * | | highest contour | + 2000 | published |
 * | --- | --- | --- | --- |
 * | inner circle, 0–10 NM | 5000 | **7000** | **7000** |
 * | 10–25 NM, sector 237°→010° | 5000 | **7000** | **7000** |
 * | 10–25 NM, sector 010°→237° | 8000 | 10,000–11,000 | 10,600 |
 *
 * Two exact hits, and the third consistent — a per-sector figure of 10,600 implies
 * a peak at 8600 ft, which is inside the 8000 contour band the scan finds there.
 *
 * ## Fourteen bands, and why the detail is kept
 *
 * VABB ships four bands, 26 rings and 680 points. This ships **fourteen bands, 563
 * rings and 14,395 points**, and the difference is not indulgence: the Alps are
 * genuinely that structured, and a field whose whole problem is the ground cannot
 * describe it in four shades. The bands run MSA 4000 to 17,000 in 1000 ft steps.
 *
 * The pipeline is VABB's — morphological **open then close**, Chaikin once, then
 * Douglas–Peucker — but on a 0.12 NM grid with a 0.24 NM brush rather than a
 * quarter-mile, which is roughly a third of the VABB proportion. Open deletes the
 * one-cell filaments the source's contour tracer leaves down every valley; close
 * fills the notches between them so a ridge reads as one mass. Area is preserved to
 * about 2% in the large bands.
 *
 * **A ring smaller than the brush gets the closing pass only.** Eroding by 0.24 NM
 * deletes anything under half a mile across, and the first pass through this file
 * lost Mont Blanc — the single MSA 17,000 ring, 0.18 sq NM — along with most of the
 * 14,000 and 15,000 summits. The highest ground is the part worth shading, so small
 * rings are rounded off and never thinned. That is VABB's rule for a band too small
 * to erode, applied per ring instead, because here one band holds both a 2000 sq NM
 * escarpment and a summit the size of a city block.
 *
 * ## No approach corridor exemption, and that is a fact about the field
 *
 * VABB needs two: full resolution from 10 to 25 NM so that real peaks under the
 * final are not generalised away, and a bare inner 10 NM so that a correctly flown
 * ILS is not a terrain violation. LSGG needs neither. **The RWY 22 final is clear of
 * terrain out to 28 NM** — it runs straight up Lake Geneva — and the nearest shaded
 * ground to the extended centreline inside 30 NM is MSA 4000 at 29 NM, where the
 * glideslope is already at 10,600. The approach here is over water, and the
 * generalisation cannot touch it.
 *
 * ## These figures exceed the field's MVA
 *
 * 8% of the airspace is shaded above `airspace.mvaFt` of 7000 — the same
 * contradiction VABB's file documents, at almost the same size, and resolved the
 * same way: the MVA is a floor on what the controller may assign, not a claim about
 * the ground. Here the shading is the more useful half of it, because south-east of
 * the field it is telling the truth: an aircraft vectored to 7000 over the Alps at
 * 20 NM really is below the minimum, and that is the game this field is.
 */
